import{et as e,mt as t,s as n,tt as r}from"./chunks/framework.DWKxYYJ1.js";import"./chunks/assets.tD9y118P.js";var i=JSON.parse(`{"title":"Dashboard","description":"Compare AI test automation methods and the latest tools. Learn how to increase QA efficiency with machine learning-based automated testing.","frontmatter":{"title":"Dashboard","description":"Compare AI test automation methods and the latest tools. Learn how to increase QA efficiency with machine learning-based automated testing.","head":[["meta",{"name":"keywords","content":"Test Automation, Testing Generative AI, Playwright, Selenium, Real-time Quality Feedback, Zero-downtime Testing, AI-based Test Automation, Continuous Testing, QAOps, TestOps, Codeless, Low-Code, Self-healing Test, Self-healing, AI Test Automation, Codeless Automation, QA Automation, Software Testing, Test Scenario Creation, Codeless Test, Natural Language Test, Test Automation Tool, Test Automation Platform, Test Efficiency, Playwright, Selenium, QAOps, TestOps, Shift-Left Testing, Shift-Right Testing"}],["meta",{"property":"og:title","content":"AI Test Automation | SyncETA"}],["meta",{"property":"og:description","content":"Reduce QA time by 80% with AI-based test automation. Set a new standard for QA with codeless test creation, natural language scenario writing, and multi-platform support."}],["meta",{"property":"og:image","content":"https://empasy.io/docs/images/favicon.png"}],["meta",{"property":"og:url","content":"https://doc.empasy.com/synceta/"}],["link",{"rel":"canonical","href":"https://empasy.io/docs/en/synceta/dashboard.html"}]],"sort":8},"headers":[],"relativePath":"en/synceta/dashboard.md","filePath":"en/synceta/dashboard.md","lastUpdated":1784590561000}`),a={name:`en/synceta/dashboard.md`};function o(n,i,a,o,s,c){return t(),e(`div`,null,[...i[0]||=[r(`<h1 id="dashboard" tabindex="-1">Dashboard <a class="header-anchor" href="#dashboard" aria-label="Permalink to “Dashboard”">​</a></h1><h2 id="test-results" tabindex="-1">Test Results <a class="header-anchor" href="#test-results" aria-label="Permalink to “Test Results”">​</a></h2><h4 id="you-can-view-the-results-by-setting-the-execution-type-period" tabindex="-1">You can view the results by setting the execution type/period. <a class="header-anchor" href="#you-can-view-the-results-by-setting-the-execution-type-period" aria-label="Permalink to “You can view the results by setting the execution type/period.”">​</a></h4><p><img src="/docs/assets/main.O_yUsi2I.png" alt="image" loading="lazy"></p><h4 id="displays-statistics-for-test-results-within-the-inquiry-period" tabindex="-1">Displays statistics for test results within the inquiry period. <a class="header-anchor" href="#displays-statistics-for-test-results-within-the-inquiry-period" aria-label="Permalink to “Displays statistics for test results within the inquiry period.”">​</a></h4><div class="info custom-block"><p class="custom-block-title custom-block-title-default">INFO</p><ol><li>Total number of scenario executions</li><li>Total number of record executions</li><li>Execution success rate of records set with &#39;High&#39; importance (Importance setting is below)</li><li>Verification success rate of verification records</li></ol></div><p><img src="/docs/assets/total.CE9PRLsd.png" alt="image" loading="lazy"></p><h4 id="how-to-check-the-detailed-execution-results-of-a-scenario" tabindex="-1">How to check the detailed execution results of a scenario <a class="header-anchor" href="#how-to-check-the-detailed-execution-results-of-a-scenario" aria-label="Permalink to “How to check the detailed execution results of a scenario”">​</a></h4><p><img src="/docs/assets/row_detail.tqxS8R47.png" alt="image" loading="lazy"></p><h4 id="auto-play" tabindex="-1">Auto Play <a class="header-anchor" href="#auto-play" aria-label="Permalink to “Auto Play”">​</a></h4><p><img src="/docs/assets/auto_play.bISZYvHo.png" alt="image" loading="lazy"></p><h4 id="you-can-easily-check-the-execution-result-by-focusing-on-the-record-at-the-time-of-the-video" tabindex="-1">You can easily check the execution result by focusing on the record at the time of the video. <a class="header-anchor" href="#you-can-easily-check-the-execution-result-by-focusing-on-the-record-at-the-time-of-the-video" aria-label="Permalink to “You can easily check the execution result by focusing on the record at the time of the video.”">​</a></h4><p><img src="/docs/assets/auto_play2.BKu32j9p.png" alt="image" loading="lazy"></p><h4 id="you-can-view-videos-from-multiple-tabs-at-once" tabindex="-1">You can view videos from multiple tabs at once. <a class="header-anchor" href="#you-can-view-videos-from-multiple-tabs-at-once" aria-label="Permalink to “You can view videos from multiple tabs at once.”">​</a></h4><p><img src="/docs/assets/open1111.DNbd75NH.png" alt="image" loading="lazy"></p><h4 id="clicking-will-scroll-to-the-corresponding-error-record" tabindex="-1">Clicking will scroll to the corresponding error record. <a class="header-anchor" href="#clicking-will-scroll-to-the-corresponding-error-record" aria-label="Permalink to “Clicking will scroll to the corresponding error record.”">​</a></h4><p><img src="/docs/assets/move.CjltsWyH.png" alt="image" loading="lazy"></p><h4 id="moves-to-the-video-at-the-time-of-record-execution" tabindex="-1">Moves to the video at the time of record execution. <a class="header-anchor" href="#moves-to-the-video-at-the-time-of-record-execution" aria-label="Permalink to “Moves to the video at the time of record execution.”">​</a></h4><p><img src="/docs/assets/move_video.DIAISZH1.png" alt="image" loading="lazy"></p><h4 id="you-can-write-comments-on-test-results" tabindex="-1">You can write comments on test results. <a class="header-anchor" href="#you-can-write-comments-on-test-results" aria-label="Permalink to “You can write comments on test results.”">​</a></h4><div class="info custom-block"><p class="custom-block-title custom-block-title-default">INFO</p><ul><li>Can tag team members using @</li></ul></div><p><img src="/docs/assets/comment.Dg7v6Fm4.png" alt="image" loading="lazy"></p><h4 id="you-can-check-tagged-comments" tabindex="-1">You can check tagged comments. <a class="header-anchor" href="#you-can-check-tagged-comments" aria-label="Permalink to “You can check tagged comments.”">​</a></h4><p><img src="/docs/assets/mention.DtAZd4xX.png" alt="image" loading="lazy"></p><h2 id="collected-information" tabindex="-1">Collected Information <a class="header-anchor" href="#collected-information" aria-label="Permalink to “Collected Information”">​</a></h2><ol><li><p><strong>Self-Information Collection</strong><br> SyncETA automatically collects and provides relevant information during regression testing based on the information collected at the time of recording.</p><div class="info custom-block"><p class="custom-block-title custom-block-title-default">INFO</p><p>Collects various information of the dom where the event occurred based on user actions.</p></div><p><img src="/docs/assets/select_dom.7297U75S.png" alt="image" loading="lazy"></p></li><li><p><strong>ConsoleError Collection</strong><br> You can check ConsoleErrors occurring on the test target page by automatically detecting and collecting them.</p><div class="info custom-block"><p class="custom-block-title custom-block-title-default">INFO</p><p>Collects and provides console Errors that occurred during the test.</p></div><p><img src="/docs/assets/console_err.DM08jiFm.png" alt="image" loading="lazy"></p></li><li><p><strong>HTML5 Validation (Feature being added)</strong><br> Automatically conducts W3C-based HTML5 validation during regression testing, and the results can be collected and utilized to improve the user experience.</p></li><li><p><strong>SSL Certificate Check</strong><br> Automatically checks and collects the expiration date of the SSL certificate of the tested page, and informs via a mailing service if the expiration is imminent.</p><div class="info custom-block"><p class="custom-block-title custom-block-title-default">INFO</p><p>Collects and provides the SSL certificate expiration date of the service where the test was conducted.</p></div></li></ol><ul><li>SSL certificate automatic renewal feature is being added ::: <img src="/docs/assets/ssl.Cxy2uzeT.png" alt="image" loading="lazy"></li></ul>`,27)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};